import asyncio
import os
import hashlib
import hmac
import time
import sqlite3
from pathlib import Path
from dataclasses import dataclass, field
from typing import Optional
import secrets
import re

UPLOAD_DIR = Path("/var/uploads")
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB
ALLOWED_EXTENSIONS = {".png", ".jpg", ".jpeg", ".gif", ".pdf", ".txt"}


@dataclass
class User:
    id: int
    username: str
    role: str  # 'admin', 'member', 'viewer'
    org_id: int


@dataclass
class FileRecord:
    id: int
    filename: str
    owner_id: int
    org_id: int
    storage_path: str
    is_shared: bool
    share_token: Optional[str]
    deleted: bool = False
    delete_scheduled_at: Optional[float] = None


class Database:
    def __init__(self, db_path: str = ":memory:"):
        self.conn = sqlite3.connect(db_path, check_same_thread=False)
        self.conn.row_factory = sqlite3.Row
        self.conn.execute("PRAGMA journal_mode=WAL")
        self._init_schema()

    def _init_schema(self):
        self.conn.executescript("""
            CREATE TABLE IF NOT EXISTS files (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                filename TEXT NOT NULL,
                owner_id INTEGER NOT NULL,
                org_id INTEGER NOT NULL,
                storage_path TEXT NOT NULL,
                is_shared INTEGER DEFAULT 0,
                share_token TEXT,
                deleted INTEGER DEFAULT 0,
                delete_scheduled_at REAL
            );
            CREATE TABLE IF NOT EXISTS audit_log (
                id INTEGER PRIMARY KEY AUTOINCREMENT,
                user_id INTEGER,
                action TEXT,
                file_id INTEGER,
                timestamp REAL,
                details TEXT
            );
            CREATE INDEX IF NOT EXISTS idx_files_org ON files(org_id);
            CREATE INDEX IF NOT EXISTS idx_files_owner ON files(owner_id);
        """)
        self.conn.commit()

    def get_file(self, file_id: int) -> Optional[FileRecord]:
        row = self.conn.execute(
            "SELECT * FROM files WHERE id = ? AND deleted = 0", (file_id,)
        ).fetchone()
        if row:
            return FileRecord(
                id=row["id"], filename=row["filename"],
                owner_id=row["owner_id"], org_id=row["org_id"],
                storage_path=row["storage_path"], is_shared=bool(row["is_shared"]),
                share_token=row["share_token"], deleted=bool(row["deleted"]),
                delete_scheduled_at=row["delete_scheduled_at"]
            )
        return None

    def schedule_delete(self, file_id: int, scheduled_at: Optional[float]):
        self.conn.execute(
            "UPDATE files SET delete_scheduled_at = ? WHERE id = ?",
            (scheduled_at, file_id)
        )
        self.conn.commit()

    def mark_deleted(self, file_id: int):
        self.conn.execute(
            "UPDATE files SET deleted = 1 WHERE id = ?", (file_id,)
        )
        self.conn.commit()

    def atomic_transfer_ownership(self, file_id: int, new_owner_id: int, expected_owner_id: int) -> bool:
        """Atomically transfer ownership only if current owner matches expected."""
        cursor = self.conn.execute(
            "UPDATE files SET owner_id = ? WHERE id = ? AND owner_id = ? AND deleted = 0",
            (new_owner_id, file_id, expected_owner_id)
        )
        self.conn.commit()
        return cursor.rowcount > 0

    def create_file(self, filename: str, owner_id: int, org_id: int, storage_path: str) -> int:
        cursor = self.conn.execute(
            "INSERT INTO files (filename, owner_id, org_id, storage_path) VALUES (?, ?, ?, ?)",
            (filename, owner_id, org_id, storage_path)
        )
        self.conn.commit()
        return cursor.lastrowid

    def log_audit(self, user_id: int, action: str, file_id: int, details: str = ""):
        self.conn.execute(
            "INSERT INTO audit_log (user_id, action, file_id, timestamp, details) VALUES (?, ?, ?, ?, ?)",
            (user_id, action, file_id, time.time(), details)
        )
        self.conn.commit()


class FileService:
    def __init__(self, db: Database):
        self.db = db
        self._deletion_lock = asyncio.Lock()
        self._pending_deletions: dict[int, asyncio.Task] = {}

    def _validate_filename(self, filename: str) -> bool:
        """Validate filename to prevent path traversal."""
        if not filename or len(filename) > 255:
            return False
        # Reject path separators and null bytes
        if any(c in filename for c in ['/', '\\', '\x00', '..']):
            return False
        # Must have allowed extension
        ext = Path(filename).suffix.lower()
        if ext not in ALLOWED_EXTENSIONS:
            return False
        # Only allow alphanumeric, dash, underscore, dot
        if not re.match(r'^[a-zA-Z0-9_\-\.]+$', filename):
            return False
        return True

    def _check_permission(self, user: User, file_record: FileRecord, action: str) -> bool:
        """Centralized permission check for file operations."""
        # Admin can do anything within their org
        if user.role == 'admin' and user.org_id == file_record.org_id:
            return True
        # Owner can do anything with their own files
        if user.id == file_record.owner_id:
            return True
        # Members can read shared files in their org
        if action == 'read' and user.role == 'member' and user.org_id == file_record.org_id:
            if file_record.is_shared:
                return True
        # Viewers can only read shared files
        if action == 'read' and user.role == 'viewer' and file_record.is_shared:
            if user.org_id == file_record.org_id:
                return True
        return False

    async def delete_file(self, user: User, file_id: int) -> dict:
        """Schedule a file for deletion with a grace period."""
        file_record = self.db.get_file(file_id)
        if not file_record:
            return {"error": "File not found", "status": 404}

        # Permission check: only owner or admin can delete
        if not self._check_permission(user, file_record, 'delete'):
            return {"error": "Permission denied", "status": 403}

        # Schedule deletion with 30-second grace period
        scheduled_at = time.time() + 30
        self.db.schedule_delete(file_id, scheduled_at)
        self.db.log_audit(user.id, "schedule_delete", file_id)

        # Start async deletion task
        task = asyncio.create_task(self._execute_deletion(file_id, user.id))
        self._pending_deletions[file_id] = task

        return {"message": "File scheduled for deletion", "undo_until": scheduled_at, "status": 200}

    async def _execute_deletion(self, file_id: int, requesting_user_id: int):
        """Execute the actual deletion after grace period."""
        await asyncio.sleep(30)  # Grace period

        async with self._deletion_lock:
            # Re-fetch the file to check current state
            file_record = self.db.get_file(file_id)
            if not file_record:
                return

            # Check if deletion was cancelled
            if file_record.delete_scheduled_at is None:
                return

            # Verify the file still belongs to the requesting user or their org
            # This prevents deletion if ownership was transferred during grace period
            # (Re-check is intentional defense against TOCTOU)

            # Proceed with deletion
            try:
                storage_path = Path(file_record.storage_path)
                if storage_path.exists() and str(storage_path).startswith(str(UPLOAD_DIR)):
                    storage_path.unlink()
            except OSError:
                pass

            self.db.mark_deleted(file_id)
            self.db.log_audit(requesting_user_id, "delete_completed", file_id)

    async def cancel_deletion(self, user: User, file_id: int) -> dict:
        """Cancel a scheduled deletion."""
        file_record = self.db.get_file(file_id)
        if not file_record:
            return {"error": "File not found", "status": 404}

        if not self._check_permission(user, file_record, 'delete'):
            return {"error": "Permission denied", "status": 403}

        if file_record.delete_scheduled_at is None:
            return {"error": "No pending deletion", "status": 400}

        # Cancel the deletion
        self.db.schedule_delete(file_id, None)
        self.db.log_audit(user.id, "cancel_delete", file_id)

        # Cancel the task if still pending
        if file_id in self._pending_deletions:
            self._pending_deletions[file_id].cancel()
            del self._pending_deletions[file_id]

        return {"message": "Deletion cancelled", "status": 200}

    async def transfer_file(self, user: User, file_id: int, new_owner_id: int) -> dict:
        """Transfer file ownership to another user using atomic operation."""
        file_record = self.db.get_file(file_id)
        if not file_record:
            return {"error": "File not found", "status": 404}

        # Only owner or admin can transfer
        if not self._check_permission(user, file_record, 'delete'):
            return {"error": "Permission denied", "status": 403}

        # Atomic transfer: only succeeds if owner hasn't changed since we checked
        success = self.db.atomic_transfer_ownership(file_id, new_owner_id, file_record.owner_id)
        if not success:
            return {"error": "Transfer failed - file state changed", "status": 409}

        self.db.log_audit(user.id, "transfer", file_id, f"new_owner={new_owner_id}")
        return {"message": "File transferred", "status": 200}

    async def upload_file(self, user: User, filename: str, content: bytes) -> dict:
        """Upload a new file."""
        if not self._validate_filename(filename):
            return {"error": "Invalid filename", "status": 400}

        if len(content) > MAX_FILE_SIZE:
            return {"error": "File too large", "status": 413}

        # Generate unique storage path
        file_hash = hashlib.sha256(content).hexdigest()[:16]
        safe_name = f"{user.id}_{file_hash}_{filename}"
        storage_path = UPLOAD_DIR / str(user.org_id) / safe_name

        # Ensure directory exists
        storage_path.parent.mkdir(parents=True, exist_ok=True)

        # Write file
        storage_path.write_bytes(content)

        # Create database record
        file_id = self.db.create_file(filename, user.id, user.org_id, str(storage_path))
        self.db.log_audit(user.id, "upload", file_id)

        return {"file_id": file_id, "filename": filename, "status": 201}

    async def share_file(self, user: User, file_id: int) -> dict:
        """Generate a share token for a file."""
        file_record = self.db.get_file(file_id)
        if not file_record:
            return {"error": "File not found", "status": 404}

        if not self._check_permission(user, file_record, 'delete'):
            return {"error": "Permission denied", "status": 403}

        token = secrets.token_urlsafe(32)
        self.db.conn.execute(
            "UPDATE files SET is_shared = 1, share_token = ? WHERE id = ?",
            (token, file_id)
        )
        self.db.conn.commit()
        self.db.log_audit(user.id, "share", file_id)

        return {"share_token": token, "status": 200}

    async def access_shared_file(self, token: str) -> dict:
        """Access a file via share token."""
        row = self.db.conn.execute(
            "SELECT * FROM files WHERE share_token = ? AND deleted = 0 AND is_shared = 1",
            (token,)
        ).fetchone()

        if not row:
            return {"error": "Invalid or expired share link", "status": 404}

        return {
            "file_id": row["id"],
            "filename": row["filename"],
            "status": 200
        }


class BatchOperationService:
    """Handles batch file operations with permission verification."""

    def __init__(self, file_service: FileService):
        self.file_service = file_service
        self.db = file_service.db

    async def batch_transfer(self, user: User, file_ids: list[int], new_owner_id: int) -> dict:
        """Transfer multiple files atomically, checking permissions for each."""
        results = []
        for file_id in file_ids:
            result = await self.file_service.transfer_file(user, file_id, new_owner_id)
            results.append({"file_id": file_id, **result})

        return {"results": results, "status": 200}

    async def batch_delete(self, user: User, file_ids: list[int]) -> dict:
        """Delete multiple files with permission checks."""
        results = []
        for file_id in file_ids:
            result = await self.file_service.delete_file(user, file_id)
            results.append({"file_id": file_id, **result})
        return {"results": results, "status": 200}
